export const restoreMonthlySalesBackupResponseInsertedHistoriesMin = 0;

export const restoreMonthlySalesBackupResponseIdenticalProductsMin = 0;

export const restoreMonthlySalesBackupResponseIdenticalSalesMin = 0;

export const restoreMonthlySalesBackupResponseIdenticalRefundsMin = 0;

export const restoreMonthlySalesBackupResponseIdenticalGoalsMin = 0;

export const restoreMonthlySalesBackupResponseIdenticalHistoriesMin = 0;



export const RestoreMonthlySalesBackupResponse = zod.object({
  "period": zod.string().regex(restoreMonthlySalesBackupResponsePeriodRegExp),
  "inserted": zod.object({
  "products": zod.number().int().min(restoreMonthlySalesBackupResponseInsertedProductsMin),
  "sales": zod.number().int().min(restoreMonthlySalesBackupResponseInsertedSalesMin),
  "refunds": zod.number().int().min(restoreMonthlySalesBackupResponseInsertedRefundsMin),
  "goals": zod.number().int().min(restoreMonthlySalesBackupResponseInsertedGoalsMin),
  "histories": zod.number().int().min(restoreMonthlySalesBackupResponseInsertedHistoriesMin)
}),
  "identical": zod.object({
  "products": zod.number().int().min(restoreMonthlySalesBackupResponseIdenticalProductsMin),
  "sales": zod.number().int().min(restoreMonthlySalesBackupResponseIdenticalSalesMin),
  "refunds": zod.number().int().min(restoreMonthlySalesBackupResponseIdenticalRefundsMin),
  "goals": zod.number().int().min(restoreMonthlySalesBackupResponseIdenticalGoalsMin),
  "histories": zod.number().int().min(restoreMonthlySalesBackupResponseIdenticalHistoriesMin)
}),
  "conflicts": zod.array(zod.object({
  "entityType": zod.enum(['product', 'sale', 'refund', 'goal', 'history']),
  "id": zod.string(),
  "reason": zod.string(),
  "blocking": zod.boolean()
}))
})


/**
 * @summary Edit a sale
 */
export const UpdateSaleParams = zod.object({
  "id": zod.coerce.string().uuid()
})

export const updateSaleBodyOneProductNameMax = 120;

export const updateSaleBodyOneQuantityMax = 2147483647;

export const updateSaleBodyOneUnitAmountCentsMin = 0;
export const updateSaleBodyOneUnitAmountCentsMax = 9007199254740991;

export const updateSaleBodyOneCustomerNameMax = 120;

export const updateSaleBodyOneNotesMax = 1000;




export const UpdateSaleBody = zod.object({
  "saleDate": zod.coerce.date(),
  "productName": zod.string().min(1).max(updateSaleBodyOneProductNameMax),
  "quantity": zod.number().int().min(1).max(updateSaleBodyOneQuantityMax),
  "unitAmountCents": zod.number().int().min(updateSaleBodyOneUnitAmountCentsMin).max(updateSaleBodyOneUnitAmountCentsMax),
  "customerName": zod.string().max(updateSaleBodyOneCustomerNameMax).nullish(),
  "notes": zod.string().max(updateSaleBodyOneNotesMax).nullable()
}).and(zod.object({
  "idempotencyKey": zod.string().uuid(),
  "expectedVersion": zod.number().int().min(1)
}))

export const updateSaleResponseCustomerNameMax = 120;




export const UpdateSaleResponse = zod.object({
  "id": zod.string().uuid(),
  "productId": zod.string().uuid().nullable(),
  "saleDate": zod.string(),
  "productName": zod.string(),
  "quantity": zod.number().int(),
  "unitAmountCents": zod.number().int(),
  "totalCents": zod.number().int(),
  "customerName": zod.string().max(updateSaleResponseCustomerNameMax).nullable(),
  "notes": zod.string().nullable(),
  "status": zod.enum(['active', 'cancelled']),
  "cancellationReason": zod.string().nullable(),
  "version": zod.number().int().min(1),
  "createdAt": zod.coerce.date(),
  "updatedAt": zod.coerce.date()
})


/**
 * @summary Cancel a sale with a required reason
 */
export const CancelSaleParams = zod.object({
  "id": zod.coerce.string().uuid()
})

export const cancelSaleBodyReasonMax = 500;




export const CancelSaleBody = zod.object({
  "reason": zod.string().min(1).max(cancelSaleBodyReasonMax),
  "expectedVersion": zod.number().int().min(1),
  "idempotencyKey": zod.string().uuid()
})

export const cancelSaleResponseCustomerNameMax = 120;




export const CancelSaleResponse = zod.object({
  "id": zod.string().uuid(),
  "productId": zod.string().uuid().nullable(),
  "saleDate": zod.string(),
  "productName": zod.string(),
  "quantity": zod.number().int(),
  "unitAmountCents": zod.number().int(),
  "totalCents": zod.number().int(),
  "customerName": zod.string().max(cancelSaleResponseCustomerNameMax).nullable(),
  "notes": zod.string().nullable(),
  "status": zod.enum(['active', 'cancelled']),
  "cancellationReason": zod.string().nullable(),
  "version": zod.number().int().min(1),
  "createdAt": zod.coerce.date(),
  "updatedAt": zod.coerce.date()
})


/**
 * @summary Read the audit history of a sale
 */
export const GetSaleHistoryParams = zod.object({
  "id": zod.coerce.string().uuid()
})

export const GetSaleHistoryResponseItem = zod.object({
  "id": zod.string().uuid(),
  "entityType": zod.string(),
  "entityId": zod.string().uuid(),
  "operation": zod.string(),
  "actorId": zod.string(),
  "beforeData": zod.record(zod.string(), zod.unknown()).nullable(),
  "afterData": zod.record(zod.string(), zod.unknown()).nullable(),
  "createdAt": zod.coerce.date()
})
export const GetSaleHistoryResponse = zod.array(GetSaleHistoryResponseItem)


